def count_cycles(m):
    if m % 3 == 0:
        return None

    visited = [False] * m
    num_cycles = 0
    for i in range(1, m):
        if not visited[i]:
            num_cycles += 1
            curr = i
            while not visited[curr]:
                visited[curr] = True
                curr = (3 * curr) % m
    return num_cycles

m_odd_cycles = []
for m in range(1, 200):
    cycles = count_cycles(m)
    if cycles is not None and cycles % 2 != 0:
        m_odd_cycles.append(m)

print("m_odd_cycles:", m_odd_cycles)
print("Sorted m_odd_cycles:", sorted(m_odd_cycles, reverse=True))

